/**
 * The leaderboard reader against real WP-16 bodies (`fixtures/leaderboard.wp16.json`, generated by
 * `arena_core.referee.leaderboard` on main 682f750 from its own test inputs): ranks, gates, provisional status,
 * paired differences, every detail line and the not-ranked board read as published.
 */
import { describe, expect, it } from "vitest";

import bodies from "../../fixtures/leaderboard.wp16.json";
import { assistantDetails, countMatrix, subjectDetails } from "./details";
import { differenceText, fprGate, metricView, parseBoard, rankStatus } from "./leaderboard";

describe("WP-16 bodies", () => {
  const a = parseBoard(bodies.assistant);
  const s = parseBoard(bodies.subject);

  it("reads the assistant board: ranks, reasons, gates and the board's provisional status", () => {
    if (a === null) throw new Error("assistant board refused");
    expect(a.rows.map((r) => [r.candidate_id, r.rank])).toEqual([
      ["A1", 1],
      ["A4", 1],
      ["A3", null],
      ["A2", null],
    ]);
    expect(a.rows[3]?.reason).toBe("ineligible: FPR above 5%");
    expect(a.manifestHash).toBe(bodies.assistant.binding.manifest_sha256);
    const [a1, , , a2] = a.rows;
    if (a1 === undefined || a2 === undefined) throw new Error("rows");
    expect(fprGate(a1).result).toBe("passed");
    expect(fprGate(a2)).toMatchObject({ result: "failed", fpr: expect.stringMatching(/^30%, interval /) as unknown });
    expect(rankStatus(a, a1)).toMatch(/^provisional ranking/);
  });

  it("reads every detail line without a raw object or NaN leaking through", () => {
    for (const row of [...(a?.rows ?? []), ...(s?.rows ?? [])]) {
      const lines = row.candidate_id.startsWith("A") ? assistantDetails(row.published) : subjectDetails(row.published);
      for (const l of lines) expect(l.value).not.toMatch(/object Object|NaN|undefined%/);
    }
    expect(countMatrix(a?.rows[0]?.published ?? {})).not.toBeNull();
  });

  it("reads the subject board unranked with its headline fidelity", () => {
    expect(s?.board).toBe("subject");
    expect(s?.rows.every((r) => r.rank === null)).toBe(true);
    expect(s?.rows[0]?.metrics["M12_subject_fidelity"]?.point).not.toBeUndefined();
  });

  it("reads the paired differences, undefined without common cells", () => {
    expect(a?.pairwise).toHaveLength(1);
    expect(a?.pairwise[0]).toMatchObject({ a: "A1", b: "A4", commonCells: 0 });
    expect(differenceText(a?.pairwise[0]?.recall ?? null)).toBe("undefined");
    expect(differenceText(metricView({ point: { num: 1, den: 10, value: 0.1 }, interval: { lo: -0.3, hi: 0.1 } }))).toBe("+10 points, interval -30 to +10 points");
    expect(differenceText(null)).toBe("not computed");
  });

  it("reads the isolation-failed board as not ranked", () => {
    const nr = parseBoard(bodies.not_ranked);
    expect(nr?.notRanked).toBe(true);
    expect(nr?.rows).toEqual([]);
  });
});
